package com.civicconnect.backend.model;

import jakarta.persistence.*;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "service_requests")
public class ServiceRequest {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    /** Generated by the database (sequence default). Read-only here; call refresh() after insert. */
    @Column(name = "reference_number", insertable = false, updatable = false)
    private String referenceNumber;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "category_id", nullable = false)
    private Category category;

    @Column(nullable = false)
    private String description;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private RequestStatus status;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 10)
    private Priority priority;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "requester_id", nullable = false)
    private User requester;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "assigned_staff_id")
    private User assignedStaff;

    /** Maintained by a database trigger on UPDATE (default now() on insert). */
    @Column(name = "updated_at", insertable = false, updatable = false)
    private Instant updatedAt;

    /** Optimistic lock (ASR-03): two staff cannot silently overwrite each other. */
    @Version
    @Column(nullable = false)
    private Long version;

    protected ServiceRequest() { }

    public ServiceRequest(Category category, String description, Priority priority, User requester) {
        this.category = category;
        this.description = description;
        this.priority = priority;
        this.requester = requester;
        this.status = RequestStatus.SUBMITTED;
    }

    public UUID getId() { return id; }
    public String getReferenceNumber() { return referenceNumber; }
    public Category getCategory() { return category; }
    public String getDescription() { return description; }
    public RequestStatus getStatus() { return status; }
    public Priority getPriority() { return priority; }
    public User getRequester() { return requester; }
    public User getAssignedStaff() { return assignedStaff; }
    public Instant getUpdatedAt() { return updatedAt; }
    public Long getVersion() { return version; }
}
